{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "L-1-[18F]FETrp, a close tryptophan analog, showed good BBB permeability and brain accumulation in an intracranial glioma mouse model by micro-PET imaging.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tryptophan itself crosses the human BBB, with PET-measured influx into the brain, supporting CNS access for closely related tryptophan analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A close tryptophan analog, 5-[18F]FEHTrp, showed low brain uptake (0.84 %ID/g) in mice, indicating that some analogs in this family have limited CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest tryptophan-analog evidence and tryptophan itself demonstrate BBB crossing and brain uptake, but some close analogs show low normal-brain uptake. On balance, direct in-vivo evidence supports meaningful CNS access, with low confidence due to conflicting analog data.",
  "evidence_gaps": [
    "No direct query-specific CNS exposure data; prediction relies on analog evidence.",
    "Conflicting brain-uptake results among close tryptophan analogs (good uptake for L-1-[18F]FETrp vs low uptake for 5-[18F]FEHTrp and [18F]FPOTrp).",
    "Glioma PET evidence may involve tumor-associated BBB disruption, limiting transfer to normal BBB conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

